'modeled_machine_obligations_pending': False, 'modeled_controller_obligations_pending': False}, 'worker-stage1-traps-armed': {'modeled_grant_consumed': True, 'modeled_worker_invocation': True, 'modeled_no_reuse_quarantine': False, 'modeled_machine_obligations_pending': False, 'modeled_controller_obligations_pending': False}}

def exact(actual, expected, label):
    if json.dumps(actual, sort_keys=True, default=lambda b: ["bytes", b.hex()]) != json.dumps(expected, sort_keys=True, default=lambda b: ["bytes", b.hex()]):
        raise ValueError(label)

def sha(content):
    return hashlib.sha256(content).hexdigest()

def safe_relative(rel):
    if type(rel) is not str or not rel or '\\' in rel or rel.startswith('/') or any(x in ('', '.', '..') for x in rel.split('/')):
        raise ValueError('unsafe relative path')
    return Path(rel)

def safe_file(root, rel):
    p = root / safe_relative(rel)
    if not p.is_file() or p.is_symlink() or p.absolute() != p.resolve() or not p.resolve().is_relative_to(root.resolve()):
        raise ValueError('unsafe file ' + rel)
    return p.read_bytes()

def validate_confirmation(c,receipt):
    exact(sha((json.dumps(c,ensure_ascii=False,sort_keys=True,indent=2)+'\n').encode()),CONFIRMATION_SHA256,'external319 confirmation')
    exact(sorted(receipt),['encoding','original_display_sha256','original_display_size_bytes','text'],'receipt fields')
    exact(receipt['encoding'],'utf8-json-text','receipt encoding')
    raw=receipt['text'].encode();exact(sha(raw),RECEIPT_SHA256,'original319 digest');exact(len(raw),42046,'original319 length')
    exact(receipt['original_display_sha256'],RECEIPT_SHA256,'receipt digest metadata');exact(receipt['original_display_size_bytes'],42046,'receipt size metadata')
    lines=receipt['text'].splitlines();exact(sum(x.startswith('PASS: ') for x in lines),547,'complete547 return');exact(lines.count('Result: PASS (547 passes, 0 failures)'),1,'full547 summary')
    log='ef0a34b (HEAD -> main, origin/main, origin/HEAD) Phase 1 step 319: plan operational integration design from confirmed strong pause'
    exact(lines.count(log),2,'matching319 HEAD origin')
    if '[main ef0a34b]' not in receipt['text'] or 'e31977c..ef0a34b  main -> main' not in receipt['text']:raise ValueError('missing319 commit/push')
    return True

def verify_history(root, policy):
    binding = policy['baseline_sha256_bindings']
    serialized = (json.dumps(binding, ensure_ascii=False, sort_keys=True, indent=2)+'\n').encode()
    exact(sha(serialized),BASELINE_JSON_SHA256,'exact accepted1458 manifest')
    exact(len(binding),1458,'accepted1458 file count')
    history = {}
    for rel,digest in binding.items():
        content = safe_file(root,rel)
        if rel == 'CHANGELOG.md':
            prefix = CHANGELOG_PREFIX.encode()
            exact(len(content),policy['accepted_changelog_size_bytes']+len(prefix),'additive CHANGELOG length')
            exact(content[:len(prefix)],prefix,'new CHANGELOG prefix')
            content = content[len(prefix):]
        exact(sha(content),digest,'accepted artifact drift '+rel)
        history[rel] = content
    return history

def validate_design(design,prior,frozen):
    exact(design,DESIGN_SPEC,'exact selected successor protocol contract')
    exact(sha((json.dumps(prior,ensure_ascii=False,sort_keys=True,indent=2)+'\n').encode()),PRIOR_PLAN_SHA256,'immutable accepted319 plan')
    exact(design['seven_requirements_bindings'],frozen['seven_review_bindings'],'seven exact frozen requirements')
    exact(design['preserved_cross_obligations'],frozen['proof_obligations'],'all ten unresolved cross obligations')
    exact(design['remaining_operational_blockers'],frozen['remaining_operational_blockers'],'operational blockers preserved')
    exact(prior['route'][1]['step'],320,'planned320 stage')
    exact(prior['route'][1]['runtime_authorized'],False,'no roadmap runtime authority')
    return True

def validate_tables(roadmap, obligations):
    exact(sha(roadmap),TABLE_HASHES[0],'exact typed roadmap')
    exact(sha(obligations),TABLE_HASHES[1],'exact obligation coverage table')
    return True

def evaluate_private_admission_case(value):
    exact(sorted(value),['case','origin','scope'],'case fields')
    exact(value['origin'],'synthetic-private-fixture','private origin')
    exact(value['scope'],'external-admission-contract-only','model scope')
    if type(value['case']) is not str or value['case'] not in MODEL_CASES:raise ValueError('unknown admission case')
    result=dict(MODEL_CASES[value['case']])
    result.update(actual_dispatch_authorized=False,actual_grant_consumed=False,actual_storage_durability_proven=False,
        actual_worker_invoked=False,actual_operational_conformance=False,actual_host_obligations_closed=False,actual_strong_safe_pause_confirmed=False,
        retry_authorized=False,recovery_authorized=False)
    return result

def simulate_private_schedule(value):
    exact(sorted(value),['events','origin','scope'],'schedule fields')
    exact(value['origin'],'synthetic-private-fixture','schedule origin');exact(value['scope'],'atomic-contract-interleaving-not-real-concurrency','schedule scope')
    if type(value['events']) is not list or len(value['events'])>20:raise ValueError('bounded schedule')
    owner=None;spent=False;invocations=0;closed=False;ack=False;denials=0;trace=[]
    for row in value['events']:
        exact(sorted(row),['actor','event'],'event schema')
        if type(row['actor']) is not int or row['actor'] not in [0,1]:raise ValueError('actor type')
        if row['event'] not in ['claim-durable-CAS','spend-launch-slot-durable','invoke-worker-once','ack','crash']:raise ValueError('event type')
        actor=row['actor'];event=row['event'];accepted=False
        if event=='crash':closed=True;accepted=True
        elif not closed:
            if event=='claim-durable-CAS' and owner is None:owner=actor;accepted=True
            elif event=='spend-launch-slot-durable' and owner==actor and not spent:spent=True;accepted=True
            elif event=='invoke-worker-once' and owner==actor and spent and invocations==0:invocations=1;accepted=True
            elif event=='ack' and owner==actor and spent:ack=True;accepted=True
        if not accepted:denials+=1
        trace.append(dict(owner=owner,spent=spent,invocations=invocations,closed=closed,event_accepted=accepted))
    return dict(modeled_owner=owner,modeled_launch_slot_spent=spent,modeled_worker_invocations=invocations,
        modeled_consumed=None if closed and owner is None else owner is not None,
        modeled_pending_controller=closed,modeled_possible_machine_obligations=closed and invocations==1,
        modeled_ack=ack,modeled_denials=denials,trace=trace,
        actual_dispatch_authorized=False,actual_grant_consumed=False,actual_worker_invoked=False,
        actual_atomicity_or_durability_proven=False,actual_operational_conformance=False,retry_authorized=False)

def run_historical(history):
    with tempfile.TemporaryDirectory(prefix='step320-exact319-') as directory:
        snapshot = Path(directory)/'slack-update'
        for rel,content in history.items():
            p = snapshot/safe_relative(rel); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(content)
        result = subprocess.run(['bash',str(snapshot/'tests/reference'/('test-'+PRIOR+'-harness.sh'))],capture_output=True)
        lines = result.stdout.decode().splitlines()
        if result.returncode or lines.count('Result: PASS (547 passes, 0 failures)')!=1 or sum(x.startswith('PASS: ') for x in lines)!=547:
            sys.stderr.buffer.write(result.stdout+result.stderr)
            raise ValueError('full exact547 predecessor acceptance failed')
        return result.stdout

def main(root,out):
    if not root.is_dir() or root.absolute()!=root.resolve():raise ValueError('unsafe repository root')
    for rel,digest in OWN_HASHES.items():exact(sha(safe_file(root,rel)),digest,'changed320 input '+rel)
    fixture=root/FIXTURE;load=lambda suffix:json.loads((fixture/(BASE+suffix)).read_bytes())
    policy,design=load('-policy.json'),load('-design.json');history=verify_history(root,policy)
    frozen=json.loads(history[FIXTURE+'/'+REQUIREMENTS_BASE+'-freeze.json']);prior=json.loads(history[FIXTURE+'/'+PRIOR+'-plan.json'])
    validate_design(design,prior,frozen);validate_confirmation(load('-checkpoint-confirmation.json'),load('-step319-user-acceptance.json'))
    validate_tables(*[(fixture/(BASE+s)).read_bytes() for s in ['-admission-states.tsv','-failure-cases.tsv']])
    payloads={BASE+s:(fixture/(BASE+s)).read_bytes() for s in SUFFIXES};log_name=BASE+'-predecessor-test.log'
    if not out.is_dir() or out.absolute()!=out.resolve():raise ValueError('output must exist without symlink ancestors')
    if any((out/name).exists() or (out/name).is_symlink() for name in list(payloads)+[log_name]):raise ValueError('occupied output; no overwrite')
    payloads[log_name]=run_historical(history);exact(verify_history(root,policy),history,'history changed during validation')
    for rel,digest in OWN_HASHES.items():exact(sha(safe_file(root,rel)),digest,'320 input changed during validation')
    created=[]
    try:
        for name,content in payloads.items():
            with (out/name).open('xb') as stream:created.append(out/name);stream.write(content)
    except BaseException:
        for p in reversed(created):p.unlink()
        raise
    print('exact_step319_acceptance\tPASS (547 passes, 0 failures)')
    print('step320_admission_design_review_status\tPASS')
    print('selected_protocol_contract\tyes')
    print('actual_dispatch_authorized\tno')
    print('actual_grant_consumed\tno')
    print('operational_readiness\tno')
    print('strong_safe_pause\tno')
    print('last_confirmed_strong_safe_pause_step\t318')
    print('next_stage_authorized\tno')

if __name__ == '__main__':
    try: main(Path(sys.argv[1]).absolute(),Path(sys.argv[2]).absolute())
    except (ValueError,OSError,KeyError,TypeError) as exc:
        print('ERROR: '+str(exc),file=sys.stderr);sys.exit(1)
